def solve(base, maximum, attempts):
    if base == 0 or maximum == 0:
        return [0] * len(attempts)

    # When attempt >= maximum.bit_length(), 2**attempt > maximum,
    # so base * 2**attempt > maximum and the result is maximum.
    # This avoids constructing astronomically large integers for huge attempts.
    threshold = maximum.bit_length()

    result = []
    for attempt in attempts:
        if attempt >= threshold:
            result.append(maximum)
        else:
            result.append(min(maximum, base * (1 << attempt)))
    return result
